import React from "react";
import volcanoUrl from "./assets/icons/volcano.svg?url";

export default function TestIcon() {
  console.log("volcanoUrl:", volcanoUrl);
  return (
    <div>
      <p>¿Se ve este SVG?</p>
      <img
        src={volcanoUrl}
        width={32}
        height={32}
        alt="Volcano icon test"
        style={{ border: "1px solid red" }}
      />
    </div>
  );
}
